    // the inner (valley) and outer (tip) points of the saw-teeth
    const dc = p => Math.hypot(p[0] - c[0], p[1] - c[1]); let ev = 0, od = 0; P.forEach((p, i) => { if (i % 2) od += dc(p); else ev += dc(p); });
